    Let $\phi_i,\psi_i\in C_{a_i-a_k}$. If
    \begin{align*}
        (f_0-\phi_{0}f_k,\ldots,&f_{k-1}-\phi_{k-1}f_k,f_{k+1}-\phi_{k+1}f_k,\ldots, f_n-\phi_nf_k)=\\
        &(f_0-\psi_{0}f_k,\ldots,f_{k-1}-\psi_{k-1}f_k,f_{k+1}-\psi_{k+1}f_k,\ldots, f_n-\psi_nf_k)
    \end{align*}
    then $\phi_i=\psi_i$.

Theorem \ref{theorem-intro1} follows from Theorem \ref{vspthm-unified}
    and Theorem \ref{Thm:VSP-main}. Theorem \ref{theorem-intro2}
    follows from Theorem \ref{vspthm-unified} and Corollary \ref{show fn is non-reduced}.
